float2 uv1;

 float2 cpow(float2 base, float ex) {
   float moduz = sqrt(base.x*base.x + base.y*base.y);
   float thetaz = atan2(base.y, base.x);
   float2 pow = float2(pow(moduz, ex)*cos(thetaz*ex), pow(moduz, ex)*sin(thetaz*ex));
   return pow;
 }

float2 uv2 (float2 uvi){float2 tmp, z;
  z = (uvi-0.5)*2;
  tmp = cpow(-abs(z+.0),.5);
  tmp = -.2 + (1 - abs( frac( tmp * q10 ) * 2 - q11 )-q12);
  return frac(tmp);
}

float3 MyGet (float2 uvi) {
  return lerp(GetPixel(uvi),GetBlur1(uvi),.2);
};


shader_body {

ret.r = MyGet(uv2((uv-.00)+.0)).r*.9;
ret.r += .3*saturate(1-2*rad) + .04;

