#define sat saturate
static const float tele = q31; 
static const float2 k1 = float2(8,16);  
static const float quality = 4, depth = q28/tele, maxdist = 8, dist0 = .5, hordist = 10;
float3 neu, rsl0, rsl, rsl2, rsl3, rsl4, ret1, screen3, sun, sky;
float2 dz, uv1, uv2;
float  dist, lprof,noise,mask, fog, delta, gmask,gmask2,water,sun0;
float  cloud, cloud2, bird, refl, dc;
static const float2 hor = texsize.z * float2 (2,0);
static const float2 ver = texsize.w * float2 (0,2);
static const float2 mov = float2 (q25,q26);
static const float day = q21, night = 1-day;
static const float3 lightcol = saturate(float3 (1+day,.4+day,.2+day));
static const float3 fogcol = lerp(lightcol,lightcol.bgr,q24)*.8 + .6;
static const float2 fogdens = float2(q23,(1-q23)*4);
static const float3 wcol = .5 + .5*(rand_preset.xyz-.5);
static const float3 t = float3(q14,q15,q16);
static const float3 s = float3(q17,q18,q19);
static const float3 ts = -cross(s,t);

float3 project  (float dist) {float z, tmp; 
  tmp = mul(-s,screen3);
  z = dist/(abs(tmp)+dist0/hordist)*sign(tmp);
  gmask = saturate(z + maxdist) * (z <= 0); 
  return float3(mul(float2x3(ts,t),cross(s*q27,screen3))*z,-z/hordist);}

float3 project2  (float dist) {float z, tmp; 
  tmp = mul(-s,screen3-float3(0,.03,0));
  z = dist/(abs(tmp)+dist0/hordist)*sign(tmp);
  z = pow(z,.7)*sign(z)*2;
  gmask2 = (z >= -maxdist) * (z <= maxdist); //#
  return float3(mul(float2x3(ts,t),cross(s,screen3))*-abs(z),-z/hordist);} //#achtung gmask2 weg wg. sun

float noise4 (float2 uvi) { float n1,n2,n3,n4,n5,zv; zv = 0.004*time;
  n1 = lum(tex2D(sampler_noise_hq, (uvi)));
  n2 = lum(tex2D(sampler_noise_hq, (uvi*2+zv)));
  n3 = lum(tex2D(sampler_noise_hq, (uvi*4+zv)));
  n4 = lum(tex2D(sampler_noise_hq, (uvi*8+zv)));
  n5 = lum(tex2D(sampler_noise_hq, (uvi*16+zv)));
  return n1 + n2/2 + n3/4 + n4/8*0- .5;}

shader_body {screen3 = float3 ((uv-float2(.5,.5-q32))*aspect.xy+float2(0,-.05*pow(uv.x-.5,2)),tele);

//PROJEKTION LAND
dist = dist0;
for (int m=1; m <= quality; m++) {
  rsl0 = project(dist);
  rsl = rsl0 +float3(mov,0);
  lprof =  lum(GetBlur1(frac(rsl.xy)).rg)-.5 ; //mittelwert null !#
  dist += -lprof/quality*depth;//rsl3.z; //#
}
neu = saturate(max(gmask,gmask2))*GetPixel(rsl.xy)*float3(1,1,0);

//WASSER
water = sat(2.5+sin(2*rsl.xy)-8*neu.g);
float2 ripple = tex2D (sampler_noise_hq,rsl.xy*(12+lprof*.1)-.2*time).rg;;
rsl.xy += water* .006*ripple*(1);
neu = lerp(neu,sat(lum(neu.rg)*wcol),water);
float reflmask = saturate(2*water+4*(neu.r-1.5*neu.g))*gmask;

rsl3 = project2(dist0); //benoetigt fuer delta, sun etc.
delta = (1-abs(rsl3.z))*gmask;
dz.x = lum(GetPixel (frac(rsl.xy-delta*hor)).rg*k1) - lum(GetPixel (frac(rsl.xy+delta*hor)).rg*k1);
dz.y = lum(GetPixel (frac(rsl.xy-delta*ver)).rg*k1) - lum(GetPixel (frac(rsl.xy+delta*ver)).rg*k1);

dz.x = 0; //nicht so toll aber geringere GPU-Last
dz *= q30;

//PROJEKTION HIMMEL
rsl4 = rsl3 + float3(dz*16*length(dz),0)*gmask;
rsl2 =  rsl4  + float3(mov,0);
uv2  =  rsl2.xy/16 +.025*noise4(rsl2.xy/8);
cloud  = lum(tex2D (sampler_noise_hq,uv2));
cloud2 = lum(tex2D (sampler_noise_hq,uv2 + float2(0,-.008)*night));
dc    = cloud-cloud2;
cloud = pow(sat(cloud-q20),1.2);

neu *= sat(day*.4+.15*q5);

//SCHATTENWURF
neu -= dz.y* gmask*(.2+night)*lightcol;

//BELEUCHTUNG
noise = noise4 (rsl.xy/16-time*.02)-.25;

//HIMMEL
float3 rsl5 = float3(rsl3.xy/hordist,rsl3.z) ;
sun0 = .15/length(rsl5+dc/2+float2(0,night*.6)) * night;
sun = pow(sun0,1)*lightcol;

float sky00 = pow(rsl5.x,2)+pow(rsl5.y-night,2)+.5; //richt.abh.#
float3 skyb = pow(sky00* (day+0.25)/4,float3(.9,.8,.4)+.2*(slow_roam_sin-.5)) ;;
float3 sky0 =  (sun)*sat(1-gmask*4) + skyb;
sky = skyb* sat(1-sun0*1-cloud) + sun + sat(.75+2*day-rsl3.y/hordist)*(cloud*q5*lightcol + dc);


//REFLEKTION
neu += sat(reflmask * (.4+.2*day)*(sky));

ret1 = lerp(neu,sky,saturate(1-2*gmask));


//HORIZONT
noise = tex2D (sampler_noise_hq,rsl.xy/4+.006*time).r-.5; //# unmoduliertes rsl nehmen !
dist = sat(pow(abs(rsl5.z-.04),fogdens.y*(2-gmask))); //blau: kuehler morgennebel #
ret1 = lerp(ret1, sat(sky0+lum(sky0)*fogcol), fogdens.x*sat(dist-gmask*(lprof*2 -noise/2)));

//Vogel
bird = GetPixel((uv-.5)+.5).b;
ret1 = ret1 * sat(1-2*bird)+saturate(GetPixel(uv).b - GetPixel(uv-.002).b)*0;


ret = ret1;
}
